INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", "vo_minigame_1013", "vo_minigame_1013_top_talk_6_002", "", "", 0, "", 6015, 0, 21);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, 0, 129811, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 0.3, 0, 1, 0, 6016, 9, 11);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", 0, "", "", "", "", "", 6017, "", 91);
