INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (7, 0, 129911, "私の班のみなさんも\n変わらず訓練に励んで\nいるようですわね\n殊勝なことです", 0.3, 0, 1, 0, 7006, 6, 11);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (7, "", 0, "", "", "", "", "", 7007, "", 91);
